import os, subprocess, time, struct, fcntl, termios, pty
EXE=os.path.abspath("executable")
def run_split(stdin_data, term="xterm-256color"):
    # stdout/stderr to pty, stdin to pipe
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24, 80, 0, 0))
    e=os.environ.copy(); e["TERM"]=term
    # stdin: pipe
    # Use Popen with stdin=PIPE, stdout=slave, stderr=slave
    p=subprocess.Popen([EXE], stdin=subprocess.PIPE, stdout=slave, stderr=slave, cwd="/tmp", env=e)
    os.close(slave)
    # write stdin data then close?
    if stdin_data is not None:
        try:
            p.stdin.write(stdin_data)
        except: pass
        try: p.stdin.close()
        except: pass
    else:
        # DEVNULL? use close?
        try: p.stdin.close()
        except: pass
    time.sleep(0.8)
    import fcntl as fc
    flags=fc.fcntl(master, fc.F_GETFL)
    fc.fcntl(master, fc.F_SETFL, flags | os.O_NONBLOCK)
    out=b""
    try:
        while True:
            try:
                d=os.read(master, 16384)
                if not d: break
                out+=d
            except BlockingIOError: break
            except OSError: break
    except: pass
    # send q
    try: os.write(master, b"q")
    except: pass
    time.sleep(0.5)
    try:
        while True:
            try:
                d=os.read(master, 16384)
                if not d: break
                out+=d
            except BlockingIOError: break
            except OSError: break
    except: pass
    try: p.wait(timeout=1)
    except: p.kill()
    try: os.close(master)
    except: pass
    return p.returncode, out

for data in [None, b"", b"\n", b"/tmp\n"]:
    rc,out=run_split(data)
    print("stdin=" + repr(data) + " => rc=" + str(rc) + " len=" + str(len(out)) + " snippet=" + repr(out[:300]))

