static int run_tui_loop(char *start_path, char *orig_arg, char *prompt_name, int is_list_temp, char *list_tmp){
    // init contexts
    for(int i=0;i<MAX_CTX;i++){ctxs[i].path[0]=0;ctxs[i].cur=0;ctxs[i].top=0;}
    cur_ctx=0;
    show_hidden=g_flag_H;
    detail_mode=g_flag_d;
    use_8color=g_flag_C;
    dirs_ctx_color=g_flag_D;
    picker_file=g_opt_p;
    picker_null=g_flag_0;
    // resolve start_path to absolute?
    char absbuf[PATH_MAX];
    if(start_path){
        if(start_path[0]=='/') strncpy(absbuf,start_path,PATH_MAX-1);
        else{
            char cwd[PATH_MAX];getcwd(cwd,sizeof(cwd));
            snprintf(absbuf,sizeof(absbuf),"%s/%s",cwd,start_path);
        }
        absbuf[PATH_MAX-1]=0;
        // normalize? remove trailing / (except root), resolve . ?
        // simplify: use realpath if exists?
        char rp[PATH_MAX];
        if(realpath(absbuf,rp)!=NULL) strncpy(absbuf,rp,PATH_MAX-1);
        else{
            // remove trailing slashes
            size_t L=strlen(absbuf);
            while(L>1&&absbuf[L-1]=='/'){absbuf[L-1]=0;L--;}
        }
        strncpy(ctxs[0].path,absbuf,PATH_MAX-1);
    }else strncpy(ctxs[0].path,".",PATH_MAX-1);
    // if orig_arg was file (exists and not dir), select it
    int select_idx=-1;
    if(orig_arg){
        struct stat st;
        if(stat(orig_arg,&st)==0 && !S_ISDIR(st.st_mode)){
            // file exists: find its parent and select basename?
            // Our ctxs[0].path currently is start_path which for file case is parent? Actually start_path passed as parent?
            // In main we set tui_path to parent for file case. So ctxs[0].path is parent.
            // Need to select basename after load.
            char *b=strrchr(orig_arg,'/');
            char *base=b?b+1:orig_arg;
            // will select after load
            select_idx=-2; // marker with base
            // store base in static? Use prompt_name? No, prompt_name is for nonexistent file prompt.
            // For existing file, base is the file to select.
            // We'll handle after load by searching for base.
            // Save base
            static char selbase[PATH_MAX];strncpy(selbase,base,PATH_MAX-1);
            // use to find index
            // We'll do after load
        }
    }
    // handle prompt for nonexistent file (without slash): need to show [path/]name prompt?
    // orig_arg nonexistent without slash: tui_path is parent, prompt_name is basename
    // We should show prompt at bottom: "[path/]name: basename" and wait for input?
    // Original shows "[path/]name: nonexistent  " with cursor, and allows editing? Pressing ESC cancels, Enter creates?
    // For simplicity, show prompt and wait for Enter/ESC. If Enter, create file? If ESC, cancel.
    // We'll implement minimal: show prompt, read line via echo? Use ncurses input?
    // For now, if prompt_name, show prompt and handle.
    int need_prompt = (prompt_name!=NULL);
    char prompt_buf[PATH_MAX];if(need_prompt)strncpy(prompt_buf,prompt_name,PATH_MAX-1);

    if(g_flag_x) xterm_save();
    ncurses_init();
    setup_colors();
    if(g_flag_x) xterm_title(ctxs[0].path);

    if(load_dir(ctxs[0].path)!=0){
        // opendir failed? Show 0/0? Original would show 0/0? Or "0 entries" to stderr and exit?
        // But for TUI (tty), opendir failure? e.g., permission? It would show empty?
        nentries=0;
    }
    // handle select_idx for existing file
    if(select_idx==-2){
        char *b=strrchr(orig_arg,'/');
        char *base=b?b+1:orig_arg;
        for(int i=0;i<nentries;i++) if(!strcmp(entries[i].name,base)){ctxs[0].cur=i;break;}
    }
    // if prompt, we need to handle before main loop? Original shows prompt immediately, with TUI behind.
    // We'll handle prompt loop first.
    if(need_prompt){
        // draw behind?
        draw_all();
        // show prompt at footer?
        int rows,cols;getmaxyx(stdscr,rows,cols);
        int r=rows-1;
        // prompt: "[path/]name: basename"
        // Original: "[path/]name: nonexistent  \b\b" ? With two spaces and backspaces?
        // For our purposes, show "[path/]name: basename"
        // Then read input: allow editing? Simplify: read keys until Enter or ESC.
        // If ESC, cancel prompt (clear need_prompt, redraw).
        // If Enter, create file? Or just cancel? Original: Enter creates file? Let's assume Enter creates empty file and selects it?
        // For test with pty sending ESC then q, ESC cancels, then q quits. Good.
        // We'll implement: loop reading getch, building buffer, on ESC break, on Enter create.
        char cur_prompt[PATH_MAX];strcpy(cur_prompt,prompt_buf);
        int done=0, create=0;
        while(!done){
            move(r,0);clrtoeol();
            char msg[PATH_MAX+32];snprintf(msg,sizeof(msg),"[path/]name: %s",cur_prompt);
            // mimic original colors? Footer blue? Use blue?
            attron(COLOR_PAIR(pair_blue));mvaddstr(r,0,msg);attroff(COLOR_PAIR(pair_blue));
            // show cursor? curs_set(1)?
            curs_set(1);
            move(r,strlen(msg));
            refresh();
            int ch=getch();
            if(ch==27){ // ESC
                done=1;create=0;
                // check for Alt+Esc? Original has Alt+Esc handling, but ignore.
            }else if(ch=='\n'||ch=='\r'||ch==KEY_ENTER){
                done=1;create=1;
            }else if(ch==KEY_BACKSPACE||ch==127||ch==8){
                size_t L=strlen(cur_prompt);if(L>0)cur_prompt[L-1]=0;
            }else if(ch>=32&&ch<127){
                size_t L=strlen(cur_prompt);if(L+1<PATH_MAX){cur_prompt[L]=ch;cur_prompt[L+1]=0;}
            }else if(ch==ERR){done=1;create=0;}
            // if user typed 'q' as part of prompt? In earlier test, sending 'q' typed into prompt (since prompt active).
