                // If cur_prompt has '/', need to mkdir?
                // Simplify: if cur_prompt contains '/', mkdir -p intermediate?
            }
            int fd=open(full,O_CREAT|O_EXCL,0644);
            if(fd>=0)close(fd);
            // reload and select?
            load_dir(ctxs[0].path);
            for(int i=0;i<nentries;i++) if(!strcmp(entries[i].name,cur_prompt)){ctxs[0].cur=i;break;}
        }
        // redraw
        draw_all();
    }else{
        draw_all();
    }

    int exit_code=0;
    int quit=0;
    while(!quit){
        int ch=getch();
        // handle mouse? ignore
        if(ch==ERR) continue;
        // translate
        Ctx *c=&ctxs[cur_ctx];
        int rows,cols;getmaxyx(stdscr,rows,cols);
        int max_show=rows-2-1;if(max_show<1)max_show=1;
        switch(ch){
            case 'q':
